"""End-to-end pipeline for cleaning up and exporting a raw cue list."""

from typing import List

from cue_timing import Cue, DEFAULT_MIN_GAP_MS, group_overlap_clusters, merge_cluster


def load_cues_from_dicts(raw_entries: List[dict]) -> List[Cue]:
    """Build Cue objects from parsed subtitle entries (e.g. from JSON)."""
    return [
        Cue(index=entry["index"], start_ms=entry["start_ms"], end_ms=entry["end_ms"], text=entry["text"])
        for entry in raw_entries
    ]


def build_export_cues(raw_cues: List[Cue], min_gap_ms: int = DEFAULT_MIN_GAP_MS) -> List[Cue]:
    """Sort, cluster, and merge overlapping cues into a clean export list."""
    sorted_cues = sorted(raw_cues, key=lambda c: c.start_ms)
    clusters = group_overlap_clusters(sorted_cues, min_gap_ms=min_gap_ms)

    export_cues: List[Cue] = []
    for cluster in clusters:
        if len(cluster) > 1:
            export_cues.append(merge_cluster(cluster))
        else:
            export_cues.append(cluster[0])

    for position, cue in enumerate(export_cues, start=1):
        cue.index = position

    return export_cues


def _format_timestamp(ms: int) -> str:
    hours, remainder = divmod(ms, 3_600_000)
    minutes, remainder = divmod(remainder, 60_000)
    seconds, millis = divmod(remainder, 1000)
    return f"{hours:02d}:{minutes:02d}:{seconds:02d},{millis:03d}"


def to_srt(cues: List[Cue]) -> str:
    """Render cues as newline-joined SRT blocks."""
    blocks = []
    for cue in cues:
        header = f"{cue.index}\n{_format_timestamp(cue.start_ms)} --> {_format_timestamp(cue.end_ms)}"
        blocks.append(f"{header}\n{cue.text}\n")
    return "\n".join(blocks)


def export_srt(raw_entries: List[dict], min_gap_ms: int = DEFAULT_MIN_GAP_MS) -> str:
    """Public entry point: turn raw subtitle entries into cleaned SRT text."""
    raw_cues = load_cues_from_dicts(raw_entries)
    export_cues = build_export_cues(raw_cues, min_gap_ms=min_gap_ms)
    return to_srt(export_cues)
